def apply_sentence_price_discount(sentence,discount):
    result=[]
    for word in sentence.split(' '):
        if len(word)>1 and word[0]=='$' and word[1:].isdigit():
            cents=int(word[1:])*(100-discount)
            word=f'${cents//100}.{cents%100:02d}'
        result.append(word)
    return ' '.join(result)

